# Count number of diagonal neighbors that are 2s
def count_diag_twos(grid, r, c):
    count = 0
    for dr, dc in [(-1,-1), (-1,1), (1,-1), (1,1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
            if grid[nr][nc] == 2:
                count += 1
    return count

