    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Horizontal fills: BOTH 2s need outward left/right diagonals
    for r in range(rows):
        twos = [c for c in range(cols) if grid[r][c] == 2]
        for i in range(len(twos) - 1):
            c1, c2 = twos[i], twos[i+1]
            gap = c2 - c1 - 1
            if gap >= 2:
                left_support = (r > 0 and r < rows-1 and 
                               grid[r-1][c1-1] == 2 and grid[r+1][c1-1] == 2)
                right_support = (r > 0 and r < rows-1 and 
                                grid[r-1][c2+1] == 2 and grid[r+1][c2+1] == 2)

                if left_support and right_support:
                    for c in range(c1+1, c2):
                        if grid[r][c] == 0:
                            result[r][c] = 1

    # Vertical fills: BOTH 2s need outward up/down diagonals, not at edge
    for c in range(cols):
        twos = [r for r in range(rows) if grid[r][c] == 2]
        for i in range(len(twos) - 1):
            r1, r2 = twos[i], twos[i+1]
            gap = r2 - r1 - 1
            if gap == 1:
                if r1 == 0 or r2 == rows-1:
