                top_support = (r1 > 0 and c > 0 and c < cols-1 and 
                              grid[r1-1][c-1] == 2 and grid[r1-1][c+1] == 2)
                bottom_support = (r2 < rows-1 and c > 0 and c < cols-1 and 
                                 grid[r2+1][c-1] == 2 and grid[r2+1][c+1] == 2)

                if top_support and bottom_support:
                    for rr in range(r1+1, r2):
                        if grid[rr][c] == 0:
                            result[rr][c] = 1

    return result

